        view_model["report_id"] = "report-" + _canonical_hash(view_model).split(":", 1)[1][:24]
        self.status = f"Report view model ready: {len(as_is_graph['nodes']) + len(to_be_graph['nodes'])} nodes"
        return Data(data=view_model)

